class ResourceHandle {
    int* internal_ptr;
public:
    ResourceHandle() : internal_ptr(nullptr) {}
    ResourceHandle(int v) : internal_ptr(new int(v)) {}
    ~ResourceHandle() { delete internal_ptr; }

    // Allows use in conditional statements (C++ idiom)
    explicit operator bool() const {
        return internal_ptr != nullptr;
    }
};

ResourceHandle r(42);
